  "def levenshtein(s1, s2):\n    if len(s1) < len(s2):\n        return levenshtein(s2, s1)\n    if len(s2) == 0:\n        return len(s1)\n    prev = range(len(s2) + 1)\n    for i, c1 in enumerate(s1):\n        curr = [i + 1]\n        for j, c2 in enumerate(s2):\n            insertions = prev[j + 1] + 1\n            deletions = curr[j] + 1\n            substitutions = prev[j] + (c1 != c2)\n            curr.append(min(insertions, deletions, substitutions))\n        prev = curr\n    return prev[-1]",
